CREATE TABLE group_m AS SELECT permissions::varchar(256)[] AS permissions FROM "group";
CREATE TABLE meeting_m AS SELECT assignment_poll_sort_poll_result_by_votes, poll_sort_poll_result_by_votes, assignment_poll_default_type, motion_poll_default_type, poll_default_type, assignment_poll_default_method, poll_default_method, assignment_poll_default_group_ids::integer[] AS assignment_poll_default_group_ids, motion_poll_default_group_ids::integer[] AS motion_poll_default_group_ids, topic_poll_default_group_ids::integer[] AS topic_poll_default_group_ids, assignment_poll_default_onehundred_percent_base::varchar(256) AS assignment_poll_default_onehundred_percent_base, motion_poll_default_onehundred_percent_base::varchar(256) AS motion_poll_default_onehundred_percent_base, poll_default_onehundred_percent_base::varchar(256) AS poll_default_onehundred_percent_base FROM "meeting";
CREATE TABLE meeting_user_m AS SELECT vote_delegated_to_id::integer AS vote_delegated_to_id FROM "meeting_user";
CREATE TABLE option_m AS SELECT yes, no, abstain, text, content_object_id::varchar(256) AS content_object_id, poll_id::integer AS poll_id, vote_ids::integer[] AS vote_ids FROM "option";
CREATE TABLE poll_m AS SELECT global_yes, global_no, global_abstain, min_votes_amount, max_votes_amount, max_votes_per_option, type, entitled_users_at_stop, votescast, votesinvalid, content_object_id::varchar(256) AS content_object_id, global_option_id::integer AS global_option_id, meeting_id::integer AS meeting_id, onehundred_percent_base::varchar(256) AS onehundred_percent_base, pollmethod::varchar(256) AS pollmethod, state::varchar(256) AS state, voted_ids::integer[] AS voted_ids, option_ids::integer[] AS option_ids FROM "poll";
CREATE TABLE poll_candidate_m AS SELECT weight, poll_candidate_list_id::integer AS poll_candidate_list_id, user_id::integer AS user_id FROM "poll_candidate";
CREATE TABLE poll_candidate_list_m AS SELECT option_id::integer AS option_id, poll_candidate_ids::integer[] AS poll_candidate_ids FROM "poll_candidate_list";
CREATE TABLE vote_m AS SELECT user_token, value, weight, user_id::integer AS user_id, delegated_user_id::integer AS delegated_user_id, option_id::integer AS option_id FROM "vote";
